{
 "command": "git ls-files && cat README* 2>/dev/null | head -50",
 "description": "List repo files and README"
}

{
 "command": "cat .engramdb/memories/invoice-retention-period*.md; cat migrations/0001_create_invoices.sql migrations/0005_create_refunds.sql; cat src/billing/invoices.py src/billing/refunds.py; cat scripts/backfill_tax.py scripts/reconcile_ledger.py; cat docs/ops/backfills.md; grep -rn -i \"retention\\|purge\\|3650\\|2555\" --exclude-dir=.engramdb . ",
 "description": "Read retention memories, schema, and similar scripts"
}

{
 "command": "cat migrations/0004_create_lines.sql migrations/0003_add_ledger_ref.sql migrations/0007_add_customers.sql scripts/migrate_dev.py scripts/seed_dev.py tests/test_db.py pyproject.toml Makefile; sed -n 1,200p .engramdb/memories/database-connections-in-deployed-environments_*.md | sed -n '/## Content/,/## Scope/p'; grep -rn \"status\" src scripts | head",
 "description": "Read schema, DB access patterns, connection memory"
}

{
 "command": "python scripts/purge_invoices.py; echo rc=$?; python scripts/purge_invoices.py --batch-size 2000; echo rc=$?; python -m pyflakes scripts/purge_invoices.py 2>/dev/null || python -m py_compile scripts/purge_invoices.py && echo ok",
 "description": "Smoke-test the script without a database"
}
